func mlBotDetectionOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (mlBotDetectionOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return mlBotDetectionOwnershipSet{ExceptionList: false, IpList: false, URLList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return mlBotDetectionOwnershipSet{ExceptionList: true, IpList: true, URLList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return mlBotDetectionOwnershipSet{ExceptionList: false, IpList: false, URLList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown ML bot detection ownership", "The configs ownership state was unknown while flattening.")
		return mlBotDetectionOwnershipSet{ExceptionList: false, IpList: false, URLList: false}, diagnostics
	}
	var configs mlBotDetectionConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return mlBotDetectionOwnershipSet{ExceptionList: !configs.ExceptionList.IsNull(), IpList: !configs.IpList.IsNull(), URLList: !configs.URLList.IsNull()}, diagnostics
}
func mlBotDetectionValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid ML bot detection item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid ML bot detection item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}
func mlBotDetectionValidatePattern(location, label, value string, pattern *regexp.Regexp, message string, diagnostics *diag.Diagnostics) {
	if !pattern.MatchString(value) {
		diagnostics.AddError("Invalid ML bot detection item", fmt.Sprintf("%s%s %s.", location, label, message))
	}
}
